/* Integer ALU: table-driven, one instruction per vector (gen/alu_vec.S,
 * generated by gen_alu.py from a model of the V8 manual). Check codes:
 * 0x100000 + row*16 + {0 result, 1 icc, 2 Y, 3 trap}; look a failing row
 * up in out/alu_vectors.txt. */
#include "macros.h"

BEGIN(t_alu_vectors, "alu: every integer ALU instruction, table of vectors")
        set alu_vec, %l0
        set alu_vec_end, %l1
        set 0x100000, %i5               /* check code of row 0 */
1:      cmp %l0, %l1
        bgeu 9f
        nop
        ld [%l0 + 24], %l6              /* flags */
        srl %l6, 10, %o0
        andcc %o0, 1, %g0
        be 2f
        nop
        srl %l6, 16, %o1                /* arm the trap catcher */
        and %o1, 0xff, %o1
        mov -1, %o0
        st %o0, [%g7 + V_TRAP_SEEN]
        st %o1, [%g7 + V_TRAP_EXPECT]
2:      ld [%l0], %l2
        ld [%l0 + 4], %o0
        ld [%l0 + 8], %o1
        ld [%l0 + 12], %o2
        call %l2
        ld [%l0 + 16], %o3
        rd %psr, %l3
        rd %y, %l4
        mov %o0, %l5
        srl %l3, PSR_ICC_SHIFT, %l3
        and %l3, 0xf, %l3

        mov %l5, %o1                    /* result */
        ld [%l0 + 20], %o2
        call check_eq
        mov %i5, %o0
        mov %l3, %o1                    /* icc */
        and %l6, 0xf, %o2
        call check_eq
        add %i5, 1, %o0
        mov %l4, %o1                    /* Y */
        ld [%l0 + 28], %o2
        call check_eq
        add %i5, 2, %o0
        srl %l6, 10, %o0                /* trap taken iff expected */
        andcc %o0, 1, %g0
        be 3f
        mov -1, %o2
        srl %l6, 16, %o2
        and %o2, 0xff, %o2
3:      ld [%g7 + V_TRAP_SEEN], %o1
        call check_eq
        add %i5, 3, %o0
        mov -1, %o0
        st %o0, [%g7 + V_TRAP_EXPECT]
        st %o0, [%g7 + V_TRAP_SEEN]

        add %i5, 16, %i5
        ba 1b
        add %l0, 32, %l0
9:
END

/* SETHI and the synthetic forms built on it */
BEGIN(t_sethi, "alu: sethi / set / %hi %lo")
        sethi %hi(0xfffffc00), %l0
        EXPECT(%l0, 0xfffffc00, 1)
        sethi %hi(0x12345678), %l0
        EXPECT(%l0, 0x12345400, 2)
        or %l0, %lo(0x12345678), %l0
        EXPECT(%l0, 0x12345678, 3)
        sethi 0, %l0
        EXPECT(%l0, 0, 4)
        mov -1, %l1                     /* simm13 sign extension */
        EXPECT(%l1, 0xffffffff, 5)
        mov -4096, %l1
        EXPECT(%l1, 0xfffff000, 6)
        mov 4095, %l1
        EXPECT(%l1, 0x00000fff, 7)
        /* %g0 reads as zero and ignores writes */
        mov 5, %g0
        mov %g0, %l2
        EXPECT(%l2, 0, 8)
        add %g0, 7, %g0
        add %g0, %g0, %l2
        EXPECT(%l2, 0, 9)
END

/* Y register: wr is "rs1 xor operand2" */
BEGIN(t_y_register, "alu: wr/rd %y, xor semantics of wr")
        set 0x12345678, %l0
        wr %l0, %y
        nop ; nop ; nop
        rd %y, %l1
        EXPECT(%l1, 0x12345678, 1)
        set 0xff00ff00, %l2
        wr %l0, %l2, %y                 /* Y = l0 ^ l2 */
        nop ; nop ; nop
        rd %y, %l1
        EXPECT(%l1, 0xed34a978, 2)
        wr %l0, 0xfff, %y
        nop ; nop ; nop
        rd %y, %l1
        EXPECT(%l1, 0x12345987, 3)
END
